\centering
\includegraphics[width=\columnwidth]{figures/fig_action_r2_threecond.pdf}
\caption{Per-layer action probe $R^2$ (image\_mean) across three training conditions: untrained VLA (random weights), Llama-2 base (pretrained, no VLA fine-tuning), and VLA-trained. All conditions share L0. Trained model peaks at L8; Llama-2 base peaks at L4; untrained collapses to negative $R^2$ at L10--L11. 50 demonstrations per task, single seed.}
\label{fig:action_r2_threecond}
\end{figure}

